  it('last remaining player wins when opponent quits', () => {
    const state = stateWith({
      phase: 'roll',
      players: [
        { id: 0, name: 'Alice', score: 0, onBoard: false, consecutiveFarkles: 0 },
        { id: 1, name: 'Bob', score: 500, onBoard: true, consecutiveFarkles: 0 },
