describe('§4 isValidSelection', () => {
  it('empty selection is invalid', () => expect(isValidSelection([], [1, 2, 3, 4, 5, 6])).toBe(false))
  it('non-scoring selection is invalid', () => expect(isValidSelection([2], [1, 2, 3])).toBe(false))
