import { useReducer, useCallback } from 'react'
import {
  createGame,
  actionRoll,
  actionToggleHold,
  actionConfirmSetAside,
  actionBank,
  actionRollAgain,
  actionAcknowledgeFarkle,
  actionQuit,
} from './engine'
import type { FarkleState, GameId } from './engine'
// GameId is only used for the type of the re-export below
type _GameId = GameId

type Action =
  | { type: 'ROLL' }
  | { type: 'TOGGLE_HOLD'; dieId: number }
  | { type: 'CONFIRM_SET_ASIDE' }
  | { type: 'BANK' }
  | { type: 'ROLL_AGAIN' }
  | { type: 'ACKNOWLEDGE_FARKLE' }
  | { type: 'QUIT' }

function reducer(state: FarkleState, action: Action): FarkleState {
  switch (action.type) {
    case 'ROLL':             return actionRoll(state)
    case 'TOGGLE_HOLD':      return actionToggleHold(state, action.dieId)
    case 'CONFIRM_SET_ASIDE': return actionConfirmSetAside(state)
    case 'BANK':             return actionBank(state)
    case 'ROLL_AGAIN':       return actionRollAgain(state)
    case 'ACKNOWLEDGE_FARKLE': return actionAcknowledgeFarkle(state)
    case 'QUIT':             return actionQuit(state)
    default:                 return state
  }
}

export function useFarkle(playerNames: string[], threeFarkleRule = true) {
  const [state, dispatch] = useReducer(
    reducer,
    undefined,
    () => createGame(playerNames, { threeFarkleRule })
  )

  return {
    state,
    roll:              useCallback(() => dispatch({ type: 'ROLL' }), []),
    toggleHold:        useCallback((dieId: number) => dispatch({ type: 'TOGGLE_HOLD', dieId }), []),
    confirmSetAside:   useCallback(() => dispatch({ type: 'CONFIRM_SET_ASIDE' }), []),
    bank:              useCallback(() => dispatch({ type: 'BANK' }), []),
    rollAgain:         useCallback(() => dispatch({ type: 'ROLL_AGAIN' }), []),
    acknowledgeFarkle: useCallback(() => dispatch({ type: 'ACKNOWLEDGE_FARKLE' }), []),
    quit:              useCallback(() => dispatch({ type: 'QUIT' }), []),
  }
}

import type { Die as DieType } from '../engine'

const FACE_DOTS: Record<number, number[][]> = {
  1: [[50, 50]],
  2: [[25, 25], [75, 75]],
  3: [[25, 25], [50, 50], [75, 75]],
  4: [[25, 25], [75, 25], [25, 75], [75, 75]],
  5: [[25, 25], [75, 25], [50, 50], [25, 75], [75, 75]],
  6: [[25, 22], [75, 22], [25, 50], [75, 50], [25, 78], [75, 78]],
}

interface DieProps {
  die: DieType
  onToggle?: () => void
  disabled?: boolean
}

export default function Die({ die, onToggle, disabled }: DieProps) {
  const dots = FACE_DOTS[die.value] ?? []

  const base = 'relative w-14 h-14 rounded-xl border-2 transition-all duration-150 select-none'

  let style = ''
  if (die.setAside) {
    style = 'bg-slate-600 border-slate-500 opacity-60 cursor-default'
  } else if (die.held) {
    style = 'bg-yellow-400 border-yellow-300 scale-110 shadow-lg shadow-yellow-500/40 cursor-pointer'
  } else if (disabled) {
    style = 'bg-slate-700 border-slate-600 cursor-default'
  } else {
    style = 'bg-white border-slate-300 hover:border-yellow-400 hover:scale-105 cursor-pointer'
  }

  const dotColor = die.held ? 'bg-slate-900' : die.setAside ? 'bg-slate-400' : 'bg-slate-800'

  return (
    <button
      onClick={disabled || die.setAside ? undefined : onToggle}
      disabled={disabled || die.setAside}
      aria-label={`Die showing ${die.value}${die.setAside ? ', set aside' : die.held ? ', selected' : ''}`}
      className={`${base} ${style}`}
    >
      {dots.map(([x, y], i) => (
        <span
          key={i}
          className={`absolute w-2.5 h-2.5 rounded-full ${dotColor}`}
          style={{ left: `${x}%`, top: `${y}%`, transform: 'translate(-50%, -50%)' }}
        />
      ))}
      {die.setAside && (
        <span className="absolute inset-0 flex items-center justify-center text-[9px] font-bold text-slate-400 uppercase tracking-widest">
          kept
        </span>
      )}
    </button>
  )
}

import Die from './Die'
import type { Die as DieType } from '../engine'

interface DiceRollerProps {
  dice: DieType[]
  onToggle: (id: number) => void
  canSelect: boolean
}

export default function DiceRoller({ dice, onToggle, canSelect }: DiceRollerProps) {
  return (
    <div className="flex flex-wrap justify-center gap-3">
      {dice.map((die) => (
        <Die
          key={die.id}
          die={die}
          onToggle={() => onToggle(die.id)}
          disabled={!canSelect}
        />
      ))}
    </div>
  )
}

import type { PlayerState } from '../engine'

interface ScoreBoardProps {
  players: PlayerState[]
  currentPlayerIndex: number
  turnTotal: number
  finalRoundTriggeredBy: number | null
  threeFarkleRule: boolean
}

export default function ScoreBoard({
  players,
  currentPlayerIndex,
  turnTotal,
  finalRoundTriggeredBy,
  threeFarkleRule,
}: ScoreBoardProps) {
  return (
    <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-6 gap-2">
      {players.map((player) => {
        const isCurrent = player.id === currentPlayerIndex
        return (
          <div
            key={player.id}
            className={`
              rounded-xl p-3 border text-center transition-all
              ${isCurrent
                ? 'bg-yellow-400/10 border-yellow-400 text-white'
                : 'bg-slate-800 border-slate-700 text-slate-400'}
            `}
          >
            <div className={`text-xs font-semibold uppercase tracking-wide mb-1 truncate
              ${isCurrent ? 'text-yellow-400' : 'text-slate-500'}`}>
              {isCurrent ? '▶ ' : ''}{player.name}
            </div>
            <div className={`text-2xl font-bold ${isCurrent ? 'text-white' : 'text-slate-300'}`}>
              {player.score.toLocaleString()}
            </div>
            {isCurrent && turnTotal > 0 && (
              <div className="text-xs text-yellow-300 mt-0.5">
                +{turnTotal.toLocaleString()} at risk
              </div>
            )}
            <div className="flex justify-center gap-1 mt-1 flex-wrap">
              {!player.onBoard && (
                <span className="text-[10px] bg-slate-700 text-slate-400 px-1.5 py-0.5 rounded-full">
                  not on board
                </span>
              )}
              {finalRoundTriggeredBy === player.id && (
                <span className="text-[10px] bg-yellow-600 text-yellow-100 px-1.5 py-0.5 rounded-full">
                  🎯 triggered
                </span>
              )}
              {threeFarkleRule && player.consecutiveFarkles > 0 && (
                <span className="text-[10px] bg-red-900 text-red-300 px-1.5 py-0.5 rounded-full">
                  💀 {player.consecutiveFarkles}/3
                </span>
              )}
            </div>
          </div>
        )
      })}
    </div>
  )
}

import { useEffect, useRef } from 'react'

interface GameLogProps {
  entries: string[]
}

export default function GameLog({ entries }: GameLogProps) {
  const bottomRef = useRef<HTMLDivElement>(null)

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: 'smooth' })
  }, [entries])

  return (
    <div className="bg-slate-900 border border-slate-700 rounded-xl p-3 h-36 overflow-y-auto text-xs font-mono">
      {entries.length === 0 && (
        <p className="text-slate-600 italic">Game log will appear here...</p>
      )}
      {entries.map((entry, i) => (
        <div
          key={i}
          className={`py-0.5 ${i === entries.length - 1 ? 'text-yellow-300' : 'text-slate-400'}`}
        >
          {entry}
        </div>
      ))}
      <div ref={bottomRef} />
    </div>
  )
}

import type { TurnPhase, PlayerState } from '../engine'

interface ActionBarProps {
  phase: TurnPhase
  currentPlayer: PlayerState
  turnTotal: number
  hasHeldDice: boolean
  onRoll: () => void
  onBank: () => void
  onRollAgain: () => void
  onConfirmSetAside: () => void
  onAcknowledgeFarkle: () => void
  onQuit: () => void
}

export default function ActionBar({
  phase,
  currentPlayer,
  turnTotal,
  hasHeldDice,
  onRoll,
  onBank,
  onRollAgain,
  onConfirmSetAside,
  onAcknowledgeFarkle,
  onQuit,
}: ActionBarProps) {
  const canBank = currentPlayer.onBoard || turnTotal >= 500

  return (
    <div className="flex flex-wrap items-center justify-center gap-3">
      {/* §13 — Roll (start of turn or hot-dice) */}
      {(phase === 'roll' || phase === 'hot-dice') && (
        <button
          onClick={onRoll}
          className="px-8 py-3 bg-yellow-400 text-slate-900 font-bold text-lg rounded-2xl hover:bg-yellow-300 active:scale-95 transition-all shadow-lg shadow-yellow-500/30"
        >
          {phase === 'hot-dice' ? '🔥 Hot Dice — Roll All 6!' : '🎲 Roll'}
        </button>
      )}

      {/* §13 — Select phase: dice selected but not confirmed */}
      {phase === 'select' && (
        <p className="text-slate-400 text-sm italic">
          Click dice to select scoring dice, then confirm
        </p>
      )}

      {/* §13 — Decide phase: at least one die held */}
      {phase === 'decide' && (
        <>
          {hasHeldDice && (
            <button
              onClick={onConfirmSetAside}
              className="px-5 py-2.5 bg-blue-500 text-white font-semibold rounded-xl hover:bg-blue-400 active:scale-95 transition-all"
            >
              ✔ Confirm Selection
            </button>
          )}
          <button
            onClick={onRollAgain}
            disabled={hasHeldDice}
            className={`px-5 py-2.5 font-semibold rounded-xl transition-all active:scale-95
              ${hasHeldDice
                ? 'bg-slate-700 text-slate-500 cursor-not-allowed'
                : 'bg-green-600 text-white hover:bg-green-500'}`}
          >
            🎲 Roll Again
          </button>
          <button
            onClick={onBank}
            disabled={!canBank || hasHeldDice}
            title={!canBank ? 'Need 500 pts to get on the board' : ''}
            className={`px-5 py-2.5 font-semibold rounded-xl transition-all active:scale-95
              ${!canBank || hasHeldDice
                ? 'bg-slate-700 text-slate-500 cursor-not-allowed'
                : 'bg-emerald-500 text-white hover:bg-emerald-400'}`}
          >
            🏦 Bank {turnTotal > 0 ? `(${turnTotal.toLocaleString()})` : ''}
          </button>
        </>
      )}

      {/* §8 — Farkle acknowledgement */}
      {phase === 'farkle' && (
        <div className="flex flex-col items-center gap-2">
          <p className="text-red-400 font-bold text-xl animate-pulse">💀 FARKLE! Turn over.</p>
          <button
            onClick={onAcknowledgeFarkle}
            className="px-6 py-2 bg-slate-700 text-white font-semibold rounded-xl hover:bg-slate-600 transition-all"
          >
            Next Player →
          </button>
        </div>
      )}

      {/* Quit button — always visible except game-over */}
      {phase !== 'game-over' && (
        <button
          onClick={onQuit}
          className="px-4 py-2 bg-red-900/60 text-red-300 border border-red-800 font-semibold rounded-xl hover:bg-red-800/60 transition-all text-sm"
        >
          🏳 I Quit
        </button>
      )}
    </div>
  )
}

import { useReducer, useCallback } from 'react'
import {
  createGame,
  actionRoll,
  actionToggleHold,
  actionConfirmSetAside,
  actionBank,
  actionRollAgain,
  actionAcknowledgeFarkle,
  actionQuit,
} from './engine'
import type { FarkleState, GameId } from './engine'
// GameId is only used for the type of the re-export below
type _GameId = GameId

type Action =
  | { type: 'ROLL' }
  | { type: 'TOGGLE_HOLD'; dieId: number }
  | { type: 'CONFIRM_SET_ASIDE' }
  | { type: 'BANK' }
  | { type: 'ROLL_AGAIN' }
  | { type: 'ACKNOWLEDGE_FARKLE' }
  | { type: 'QUIT' }

function reducer(state: FarkleState, action: Action): FarkleState {
  switch (action.type) {
    case 'ROLL':             return actionRoll(state)
    case 'TOGGLE_HOLD':      return actionToggleHold(state, action.dieId)
    case 'CONFIRM_SET_ASIDE': return actionConfirmSetAside(state)
    case 'BANK':             return actionBank(state)
    case 'ROLL_AGAIN':       return actionRollAgain(state)
    case 'ACKNOWLEDGE_FARKLE': return actionAcknowledgeFarkle(state)
    case 'QUIT':             return actionQuit(state)
    default:                 return state
  }
}

export function useFarkle(playerNames: string[], threeFarkleRule = true) {
  const [state, dispatch] = useReducer(
    reducer,
    undefined,
    () => createGame(playerNames, { threeFarkleRule })
  )

  return {
    state,
    roll:              useCallback(() => dispatch({ type: 'ROLL' }), []),
    toggleHold:        useCallback((dieId: number) => dispatch({ type: 'TOGGLE_HOLD', dieId }), []),
    confirmSetAside:   useCallback(() => dispatch({ type: 'CONFIRM_SET_ASIDE' }), []),
    bank:              useCallback(() => dispatch({ type: 'BANK' }), []),
    rollAgain:         useCallback(() => dispatch({ type: 'ROLL_AGAIN' }), []),
    acknowledgeFarkle: useCallback(() => dispatch({ type: 'ACKNOWLEDGE_FARKLE' }), []),
    quit:              useCallback(() => dispatch({ type: 'QUIT' }), []),
  }
}

